void printUuid(sal_uInt8* pNode)
{
    for (sal_Int32 i1 = 0; i1 < 4; i1++)
    {
        for (sal_Int32 i2 = 0; i2 < 4; i2++)
        {
            sal_uInt8 nValue = pNode[i1 * 4 + i2];
            if (nValue < 16)
            {
                printf("0");
            }
            printf("%02x", nValue);
        }
        if (i1 == 3)
            break;
        //printf( "-" );
    }
}
// ----------------------------------- Main -----------------------------------
SAL_IMPLEMENT_MAIN()
{
    sal_uInt8 pTargetUUID[16];
    rtl_getGlobalProcessId(pTargetUUID);
    printUuid(pTargetUUID);
    return 1;
}
